//! Differential test: `categorize_bulk_write_rows` against real upstream output.
//!
//! The fixtures in `testdata/` are **upstream's own output**, produced by running
//! `categorizeBulkWriteRows` (`src/rx-storage-helper.ts:205`) from the pinned
//! checkout (`3b763ee17`, v17.6.0) in Node, over a seeded random corpus of 600
//! write batches. They are generated by
//! `/tmp/rxdb-oracle/categorize-gen.mts`, which loads upstream through the
//! reprovisionable bundle `xtask/vectors/vendor.mjs` (lane C's).
//!
//! Why the fixtures live here rather than in `testdata/vectors/`: lane C owns the
//! committed oracle families and its brief lists `bulk-write-categorization.json`
//! as family 4, not yet published. These files are this crate's own check against
//! upstream in the meantime, and they are recorded as such — they are *not* a
//! substitute for the family when it lands, and they carry the same provenance
//! header so a reviewer can see exactly which commit produced them.
//!
//! The corpus deliberately covers:
//!
//! * inserts, updates, deletes and resurrections (`INSERT` for a document that was
//!   `_deleted` before and is not now);
//! * conflicts from a missing `previous` and from a stale `previous`, against live
//!   documents *and* tombstones;
//! * rows for documents that are not in the snapshot at all;
//! * multiple rows for the same document in one batch;
//! * attachment adds, updates and removals, plus the `510`-without-payload case,
//!   since that is the rule with the most branches.
//!
//! Any disagreement is a port bug until proven otherwise: the oracle must not be
//! adjusted to match this implementation.

use std::collections::HashMap;

use dxdb_storage::{
    categorize_bulk_write_rows, AttachmentData, AttachmentWriteData, BulkWriteRow, DocumentData,
    DocumentWriteData,
};
use serde::Deserialize;
use serde_json::Value;

/// One oracle case: the stored snapshot, the rows, and upstream's summary.
#[derive(Debug, Deserialize)]
struct Case {
    why: String,
    #[serde(rename = "hasAttachments")]
    has_attachments: bool,
    #[serde(rename = "docsInDb")]
    docs_in_db: Vec<DocJson>,
    rows: Vec<RowJson>,
    /// Set when upstream threw. The corpus has none today; the field exists so a
    /// future generator that hits an upstream throw is representable rather than
    /// silently dropped.
    #[serde(default)]
    threw: Option<String>,
    expected: Option<Expected>,
}

/// A document as the oracle stores it: a bare JSON object. The `id` is read from
/// the `id` field at use sites, which keeps this faithful to the fixture.
#[derive(Debug, Deserialize)]
struct DocJson(Value);

impl DocJson {
    fn id(&self) -> String {
        self.0
            .get("id")
            .and_then(Value::as_str)
            .expect("oracle document has an id")
            .to_string()
    }
}

#[derive(Debug, Deserialize)]
struct RowJson {
    #[serde(default)]
    previous: Option<DocJson>,
    document: DocJson,
}

/// Upstream's `CategorizeBulkWriteRowsOutput`, reduced to what is observable.
#[derive(Debug, Deserialize, PartialEq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    bulk_insert_doc_ids: Vec<String>,
    bulk_update_doc_ids: Vec<String>,
    error_statuses: Vec<u16>,
    error_document_ids: Vec<String>,
    error_attachment_ids: Vec<Option<String>>,
    error_has_document_in_db: Vec<bool>,
    events: Vec<ExpectedEvent>,
    event_bulk_context: String,
    newest_row_id: Option<String>,
    newest_row_lwt: Option<f64>,
    attachments_add: Vec<(String, String, String)>,
    attachments_remove: Vec<(String, String, String)>,
    attachments_update: Vec<(String, String, String)>,
}

#[derive(Debug, Deserialize, PartialEq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct ExpectedEvent {
    document_id: String,
    operation: String,
    has_previous: bool,
    document_deleted: bool,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    #[serde(rename = "caseCount")]
    case_count: usize,
    cases: Vec<Case>,
}

fn load_fixtures() -> Vec<Case> {
    let mut all = Vec::new();
    for part in 1..=3 {
        let path = format!(
            "{}/testdata/cases-{part}.json",
            env!("CARGO_MANIFEST_DIR")
        );
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|error| panic!("read {path}: {error}"));
        let fixture: Fixture = serde_json::from_str(&text)
            .unwrap_or_else(|error| panic!("parse {path}: {error}"));
        assert_eq!(
            fixture.cases.len(),
            fixture.case_count,
            "{path} caseCount disagrees with cases"
        );
        all.extend(fixture.cases);
    }
    all
}

/// Reconstructs a [`DocumentWriteData`] from the oracle's JSON.
///
/// The generator encodes a supplied attachment payload as a `__blob` marker object,
/// because a real `Blob` is not JSON. Any other value inside `_attachments` is a
/// stub with no payload, which is the case upstream treats as "missing data".
fn to_document(document: &DocJson) -> DocumentData {
    DocumentData::from_value(document.0.clone()).expect("oracle document is an object")
}

fn to_write_data(document: &DocJson) -> DocumentWriteData {
    let mut payloads = std::collections::BTreeMap::new();
    let mut stubs = Vec::new();
    if let Some(attachments) = document.0.get("_attachments").and_then(Value::as_object) {
        for (attachment_id, stub) in attachments {
            let Some(stub_object) = stub.as_object() else {
                continue;
            };
            let digest = stub_object
                .get("digest")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();
            let length = stub_object.get("length").and_then(Value::as_u64).unwrap_or(0);
            let content_type = stub_object
                .get("type")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();
            stubs.push((
                attachment_id.clone(),
                AttachmentData {
                    length,
                    content_type,
                    digest,
                },
            ));
            if let Some(marker) = stub_object.get("data") {
                // The marker's payload is the object itself so the bytes are
                // stable across runs; the digest is what the port reasons about.
                payloads.insert(
                    attachment_id.clone(),
                    serde_json::to_vec(marker).expect("marker serialises"),
                );
            }
        }
    }
    let mut document =
        DocumentData::from_value(document.0.clone()).expect("oracle document is an object");
    // Normalise to stub-only, then re-insert through the typed path so the port
    // sees exactly what a real caller would produce.
    document.set("_attachments", Value::Object(Default::default()));
    let mut write = DocumentWriteData::new(document);
    for (attachment_id, stub) in stubs {
        write.insert_attachment(
            &attachment_id,
            AttachmentWriteData {
                stub,
                data: payloads.remove(&attachment_id),
            },
        );
    }
    write
}

fn row_of(row: &RowJson) -> BulkWriteRow {
    BulkWriteRow {
        previous: row.previous.as_ref().map(to_document),
        document: to_write_data(&row.document),
    }
}

/// Runs the port and reduces its output the same way the oracle reduced upstream's.
fn run_port(case: &Case) -> Option<Expected> {
    let docs_in_db: HashMap<String, DocumentData> = case
        .docs_in_db
        .iter()
        .map(|document| (document.id(), to_document(document)))
        .collect();
    let rows: Vec<BulkWriteRow> = case.rows.iter().map(row_of).collect();

    let output = categorize_bulk_write_rows(
        "id",
        &docs_in_db,
        &rows,
        "oracle-ctx",
        case.has_attachments,
    );

    let plain = |rows: &[dxdb_storage::BulkWriteRowProcessed]| {
        rows.iter()
            .map(|row| row.document.id("id").expect("row has an id").to_string())
            .collect::<Vec<_>>()
    };

    let events = output
        .events
        .iter()
        .map(|event| ExpectedEvent {
            document_id: event.document_id.clone(),
            operation: event.operation.as_str().to_string(),
            has_previous: event.previous_document_data.is_some(),
            document_deleted: event.document_data.is_deleted(),
        })
        .collect();

    let triple = |adds: &[(String, String, String)]| {
        adds.iter()
            .map(|(document, attachment, digest)| {
                (document.clone(), attachment.clone(), digest.clone())
            })
            .collect::<Vec<_>>()
    };

    Some(Expected {
        bulk_insert_doc_ids: plain(&output.bulk_insert_docs),
        bulk_update_doc_ids: plain(&output.bulk_update_docs),
        error_statuses: output.error.iter().map(|error| error.status()).collect(),
        error_document_ids: output
            .error
            .iter()
            .map(|error| error.document_id().to_string())
            .collect(),
        error_attachment_ids: output
            .error
            .iter()
            .map(|error| match error {
                dxdb_storage::WriteError::Attachment { attachment_id, .. } => {
                    Some(attachment_id.clone())
                }
                _ => None,
            })
            .collect(),
        error_has_document_in_db: output
            .error
            .iter()
            .map(|error| match error {
                dxdb_storage::WriteError::Conflict { document_in_db, .. } => document_in_db.is_some(),
                dxdb_storage::WriteError::Attachment { document_in_db, .. } => {
                    document_in_db.is_some()
                }
                _ => false,
            })
            .collect(),
        events,
        // Upstream copies the caller's context onto the bulk; the port does the
        // same, and this is the assertion that it was threaded through.
        event_bulk_context: "oracle-ctx".to_string(),
        newest_row_id: output.checkpoint.as_ref().map(|checkpoint| checkpoint.id.clone()),
        newest_row_lwt: output.checkpoint.as_ref().map(|checkpoint| checkpoint.lwt),
        attachments_add: triple(&output
            .attachments_add
            .iter()
            .map(|add| {
                (
                    add.document_id.clone(),
                    add.attachment_id.clone(),
                    add.digest.clone(),
                )
            })
            .collect::<Vec<_>>()),
        attachments_remove: triple(&output
            .attachments_remove
            .iter()
            .map(|remove| {
                (
                    remove.document_id.clone(),
                    remove.attachment_id.clone(),
                    remove.digest.clone(),
                )
            })
            .collect::<Vec<_>>()),
        attachments_update: triple(&output
            .attachments_update
            .iter()
            .map(|update| {
                (
                    update.document_id.clone(),
                    update.attachment_id.clone(),
                    update.digest.clone(),
                )
            })
            .collect::<Vec<_>>()),
    })
}

/// The whole oracle corpus, case by case.
///
/// One `#[test]` for the corpus rather than 600 generated tests: a failure prints
/// the case name and the precise field that disagrees, which is what a reviewer
/// needs, and 600 separate test names would bury the signal.
#[test]
fn matches_upstream_categorize_bulk_write_rows() {
    let cases = load_fixtures();
    assert!(
        cases.len() >= 600,
        "expected the full 600-case corpus, found {}",
        cases.len()
    );

    let mut failures = Vec::new();
    let mut compared = 0usize;
    for case in &cases {
        let Some(expected) = &case.expected else {
            // Upstream threw. Nothing in the current corpus takes this path; if a
            // future generator produces one, it must be classified by hand rather
            // than silently skipped, so it is reported as a failure to classify.
            if case.threw.is_some() {
                failures.push(format!(
                    "{}: upstream threw ({:?}) and the port has no equivalent classification",
                    case.why, case.threw
                ));
            }
            continue;
        };
        compared += 1;
        let actual = run_port(case).expect("port runs");
        if &actual != expected {
            failures.push(format!(
                "{}: mismatch\n  expected: {}\n  actual:   {}",
                case.why,
                serde_json::to_string(expected).expect("expected serialises"),
                serde_json::to_string(&actual).expect("actual serialises"),
            ));
        }
    }

    assert!(compared > 0, "no cases were compared");
    assert!(
        failures.is_empty(),
        "{} of {} oracle cases disagree with upstream:\n{}",
        failures.len(),
        compared,
        failures.join("\n\n")
    );
}

/// The corpus must actually exercise every branch, or a green run proves little.
#[test]
fn corpus_covers_every_decision_branch() {
    let cases = load_fixtures();
    let mut inserts = 0;
    let mut updates = 0;
    let mut deletes = 0;
    let mut resurrections = 0;
    let mut conflicts = 0;
    let mut attachment_errors = 0;
    let mut attachment_writes = 0;
    let mut batches_without_events = 0;

    for case in &cases {
        let Some(expected) = &case.expected else {
            continue;
        };
        inserts += expected.bulk_insert_doc_ids.len();
        updates += expected.bulk_update_doc_ids.len();
        for status in &expected.error_statuses {
            match *status {
                409 => conflicts += 1,
                510 => attachment_errors += 1,
                _ => {}
            }
        }
        for event in &expected.events {
            match event.operation.as_str() {
                "INSERT" if event.has_previous => resurrections += 1,
                "INSERT" => inserts += 0,
                "DELETE" => deletes += 1,
                _ => {}
            }
        }
        attachment_writes += expected.attachments_add.len()
            + expected.attachments_update.len()
            + expected.attachments_remove.len();
        if expected.events.is_empty() && !expected.error_statuses.is_empty() {
            batches_without_events += 1;
        }
    }

    assert!(inserts > 100, "corpus must exercise inserts (got {inserts})");
    assert!(updates > 50, "corpus must exercise updates (got {updates})");
    assert!(deletes > 20, "corpus must exercise deletes (got {deletes})");
    assert!(
        resurrections > 5,
        "corpus must exercise tombstones coming back (got {resurrections})"
    );
    assert!(
        conflicts > 100,
        "corpus must exercise conflicts (got {conflicts})"
    );
    assert!(
        attachment_errors > 5,
        "corpus must exercise 510 attachment errors (got {attachment_errors})"
    );
    assert!(
        attachment_writes > 10,
        "corpus must exercise attachment side effects (got {attachment_writes})"
    );
    assert!(
        batches_without_events > 10,
        "corpus must exercise error-only batches, the 'emit no empty bulk' rule (got {batches_without_events})"
    );
}

/// Resurrection is reported as `INSERT`; the corpus must contain the case where
/// the *only* difference between two otherwise identical rows is the previous
/// tombstone, so an implementation that always says `UPDATE` fails here.
#[test]
fn resurrection_and_update_are_distinguished_by_the_previous_deleted_flag() {
    let cases = load_fixtures();
    let mut saw_resurrection = false;
    let mut saw_plain_update = false;
    for case in &cases {
        let Some(expected) = &case.expected else {
            continue;
        };
        for event in &expected.events {
            if event.operation == "INSERT" && event.has_previous && !event.document_deleted {
                saw_resurrection = true;
            }
            if event.operation == "UPDATE" {
                saw_plain_update = true;
            }
        }
    }
    assert!(saw_resurrection, "no resurrection case in the corpus");
    assert!(saw_plain_update, "no plain-update case in the corpus");
}

/// The oracle's provenance travels with the data so a reader can tell where it
/// came from without trusting a comment.
#[test]
fn fixtures_record_their_upstream_provenance() {
    let path = format!(
        "{}/testdata/cases-1.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path).expect("fixture exists");
    let header: Value = serde_json::from_str(&text).expect("fixture is JSON");
    assert_eq!(
        header.get("rxdbCommit").and_then(Value::as_str),
        Some("3b763ee17d62bc96cfae556ea0ccf92f9891c8c1"),
        "fixture must name the pinned upstream commit"
    );
    assert_eq!(
        header.get("source").and_then(Value::as_str),
        Some("src/rx-storage-helper.ts:205 categorizeBulkWriteRows"),
        "fixture must name the upstream function it records"
    );
    // The header must say what this corpus *adds*, now that lane C's committed family
    // exists. An earlier version said it was a substitute for a family that did not
    // exist yet; that became false the moment the family landed, so the marker is the
    // claim, not the word "PRIVATE".
    let comment = header
        .get("$comment")
        .and_then(Value::as_str)
        .unwrap_or_default();
    assert!(
        comment.starts_with("ADDITIONAL check"),
        "fixture must declare itself an addition to the committed family, got: {comment}"
    );
    assert!(
        comment.contains("bulk-write-categorization.json"),
        "fixture must name the committed family it complements"
    );
    assert!(
        comment.contains("randomised"),
        "fixture must say what it adds: randomised sequences rather than curated cases"
    );
}
